package com.smarthub.plus;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;
public class ReceiverSignalReadingTest {
 private JSONObject sample()throws Exception{return new JSONObject("{iTunerIndex:0,iTpId:3976,bLocked:1,iSignalStrength:80,iSignalQuality:68,iSigSNR:6.79,iSigBER:0,signalFormat:'DVBS2 QPSK 4/5'}");}
 @Test public void actualReceiverFieldsKeepTheirUnits()throws Exception{ReceiverSignalReading s=ReceiverSignalReading.parse(sample(),0);assertEquals("80%",s.value("strength"));assertEquals("68%",s.value("quality"));assertEquals("6.79 dB",s.value("snr"));assertEquals("0",s.value("ber"));assertEquals(3976,s.tp);}
 @Test public void missingFieldsNeverBecomeZero()throws Exception{ReceiverSignalReading s=ReceiverSignalReading.parse(new JSONObject("{iTunerIndex:0,iSignalQuality:68}"),0);assertEquals("",s.value("strength"));assertEquals("",s.value("snr"));assertEquals("",s.value("ber"));assertEquals(-1,s.locked);}
 @Test public void genuineZeroAndUnlockedStateArePreserved()throws Exception{ReceiverSignalReading s=ReceiverSignalReading.parse(new JSONObject("{iTunerIndex:0,bLocked:0,iSignalStrength:0,iSignalQuality:0,iSigSNR:0,iSigBER:0}"),0);assertEquals(0,s.locked);assertEquals("0%",s.value("strength"));assertEquals("0.00 dB",s.value("snr"));}
 @Test public void wrongFrontendIsRejected()throws Exception{try{ReceiverSignalReading.parse(sample().put("iTunerIndex",1),0);fail();}catch(java.io.IOException expected){}}
 @Test public void invalidMetricsAreNotClampedIntoCredibleReadings()throws Exception{ReceiverSignalReading s=ReceiverSignalReading.parse(sample().put("iSignalQuality",101).put("iSigSNR","NaN").put("iSigBER",-1),0);assertEquals("",s.value("quality"));assertEquals("",s.value("snr"));assertEquals("",s.value("ber"));try{ReceiverSignalReading.parse(new JSONObject("{iTunerIndex:0}"),0);fail();}catch(java.io.IOException expected){}}
 @Test public void onlyTheReadStatusSuccessPacketIsAccepted()throws Exception{String json=sample().toString();assertNotNull(ReceiverSignalReading.packet("Tuner\n0003\nSUCCESS:"+json,0));for(String wrong:new String[]{"Tuner\n0002\nSUCCESS:","Tuner\n0003\nERROR:","EPG_TDT\n0003\nSUCCESS:"})assertNull(ReceiverSignalReading.packet(wrong+json,0));assertNull(ReceiverSignalReading.packet("Tuner\n0003\nSUCCESS:",0));}
 @Test public void oldOtherChannelAndFutureSnapshotsAreUnavailable(){assertTrue(ReceiverSignalReading.fresh("a","a",10000,9999));assertFalse(ReceiverSignalReading.fresh("b","a",10000,9999));assertFalse(ReceiverSignalReading.fresh("a","a",14000,10000));assertFalse(ReceiverSignalReading.fresh("a","a",10000,10001));assertFalse(ReceiverSignalReading.fresh("a","a",1000,0));}
 @Test public void fractionalBerAndNullFormatAreNotLost()throws Exception{ReceiverSignalReading s=ReceiverSignalReading.parse(sample().put("iSigBER",0.0000001).put("signalFormat",JSONObject.NULL),0);assertEquals("0.0000001",s.value("ber"));assertEquals("",s.format);}
 @Test public void negativeDbSignalToNoiseIsSupported()throws Exception{assertEquals("-1.25 dB",ReceiverSignalReading.parse(sample().put("iSigSNR",-1.25),0).value("snr"));}
}
